import Foundation

/// A point-in-time snapshot of the user's cognitive state.
/// Generated by the CognitiveModel using health data, time of day, task history, and self-reports.
public struct CognitiveSnapshot: Identifiable, Codable, Sendable {
    public var id: String
    public var energy: EnergyLevel
    public var energyScore: Double          // 0.0 - 1.0
    public var stressScore: Double          // 0.0 - 1.0
    public var focusCapacity: Double        // 0.0 - 1.0
    public var recoveryScore: Double        // 0.0 - 1.0
    public var sleepDebtHours: Double       // accumulated sleep debt
    public var availableMinutes: Int        // estimated free time remaining today
    public var contextNotes: String         // AI-generated context description
    public var executiveFunctionScore: Int  // 0-100, holistic EF score
    public var recommendedTaskDifficulty: TaskDifficulty
    public var timestamp: Date
    public var userId: String
    
    public init(
        id: String = UUID().uuidString,
        energy: EnergyLevel = .moderate,
        energyScore: Double = 0.5,
        stressScore: Double = 0.3,
        focusCapacity: Double = 0.5,
        recoveryScore: Double = 0.5,
        sleepDebtHours: Double = 0,
        availableMinutes: Int = 480,
        contextNotes: String = "",
        executiveFunctionScore: Int = 50,
        recommendedTaskDifficulty: TaskDifficulty = .medium,
        timestamp: Date = Date(),
        userId: String = ""
    ) {
        self.id = id
        self.energy = energy
        self.energyScore = energyScore
        self.stressScore = stressScore
        self.focusCapacity = focusCapacity
        self.recoveryScore = recoveryScore
        self.sleepDebtHours = sleepDebtHours
        self.availableMinutes = availableMinutes
        self.contextNotes = contextNotes
        self.executiveFunctionScore = executiveFunctionScore
        self.recommendedTaskDifficulty = recommendedTaskDifficulty
        self.timestamp = timestamp
        self.userId = userId
    }
}

/// Daily health summary — aggregated from HealthKit data.
/// Only summaries (not raw data) are synced to Firebase.
public struct HealthSummary: Identifiable, Codable, Sendable {
    public var id: String
    public var date: Date
    
    // Sleep
    public var totalSleepMinutes: Double?
    public var deepSleepMinutes: Double?
    public var remSleepMinutes: Double?
    public var coreSleepMinutes: Double?
    public var awakeMinutes: Double?
    public var sleepQualityScore: Double?   // 0.0 - 1.0
    public var bedtime: Date?
    public var wakeTime: Date?
    
    // Heart
    public var restingHeartRate: Double?
    public var averageHeartRate: Double?
    public var hrvAverage: Double?          // SDNN in ms
    public var hrvTrend: String?            // "improving", "declining", "stable"
    
    // Activity
    public var stepCount: Int?
    public var activeCalories: Double?
    public var exerciseMinutes: Int?
    public var standHours: Int?
    public var workoutCount: Int?
    public var workoutTypes: [String]?
    
    // Other
    public var bloodOxygen: Double?
    public var wristTemperature: Double?
    public var mindfulMinutes: Int?
    public var waterIntakeMl: Double?
    
    // AI-generated
    public var aiInsight: String?
    public var recoveryRecommendation: String?
    
    public var userId: String
    
    public init(
        id: String = UUID().uuidString,
        date: Date = Date(),
        userId: String = ""
    ) {
        self.id = id
        self.date = date
        self.userId = userId
    }
}

/// A semantic memory entry — part of the "AI Memory" system.
/// Stores text with embedding vectors for semantic search.
public struct MemoryEntry: Identifiable, Codable, Sendable {
    public var id: String
    public var content: String
    public var summary: String
    public var lifeArea: LifeArea?
    public var tags: [String]
    public var embeddingVector: [Double]?
    public var sourceType: String          // "task", "inbox", "conversation", "manual"
    public var sourceId: String?
    public var importance: Double           // 0.0 - 1.0
    public var createdAt: Date
    public var lastAccessedAt: Date
    public var accessCount: Int
    public var userId: String
    
    public init(
        id: String = UUID().uuidString,
        content: String,
        summary: String = "",
        lifeArea: LifeArea? = nil,
        tags: [String] = [],
        embeddingVector: [Double]? = nil,
        sourceType: String = "manual",
        sourceId: String? = nil,
        importance: Double = 0.5,
        createdAt: Date = Date(),
        lastAccessedAt: Date = Date(),
        accessCount: Int = 0,
        userId: String = ""
    ) {
        self.id = id
        self.content = content
        self.summary = summary
        self.lifeArea = lifeArea
        self.tags = tags
        self.embeddingVector = embeddingVector
        self.sourceType = sourceType
        self.sourceId = sourceId
        self.importance = importance
        self.createdAt = createdAt
        self.lastAccessedAt = lastAccessedAt
        self.accessCount = accessCount
        self.userId = userId
    }
}

/// Productivity session tracked from the macOS app.
public struct ProductivitySession: Identifiable, Codable, Sendable {
    public var id: String
    public var appName: String
    public var windowTitle: String?
    public var category: ProductivityCategory
    public var durationSeconds: Int
    public var startedAt: Date
    public var endedAt: Date
    public var isIdleTime: Bool
    public var userId: String
    
    public init(
        id: String = UUID().uuidString,
        appName: String,
        windowTitle: String? = nil,
        category: ProductivityCategory = .neutral,
        durationSeconds: Int = 0,
        startedAt: Date = Date(),
        endedAt: Date = Date(),
        isIdleTime: Bool = false,
        userId: String = ""
    ) {
        self.id = id
        self.appName = appName
        self.windowTitle = windowTitle
        self.category = category
        self.durationSeconds = durationSeconds
        self.startedAt = startedAt
        self.endedAt = endedAt
        self.isIdleTime = isIdleTime
        self.userId = userId
    }
}

/// Categories for productivity tracking.
public enum ProductivityCategory: String, Codable, CaseIterable, Sendable {
    case deepWork = "Deep Work"
    case communication = "Communication"
    case planning = "Planning"
    case creative = "Creative"
    case learning = "Learning"
    case entertainment = "Entertainment"
    case social = "Social Media"
    case neutral = "Neutral"
    case idle = "Idle"
}

