    public var userId: String
    public var createdAt: Date
    
    public init(
        id: String = UUID().uuidString,
        date: Date = Date(),
        tasksCompleted: Int = 0,
        tasksCreated: Int = 0,
        tasksDeferred: Int = 0,
        totalFocusMinutes: Int = 0,
        longestFocusStreak: Int = 0,
